R["oh__@wingedcatninja"]="{['Version']=1774,['eu']={[32]={['O']=19749,['N']='Halcyon House',['D']='nothing here just quick teleport',['C']=1.006000,},[49]={['O']=19325,['N']='The Bad Place',['D']='Witches\\' Festival Themed house. ',['C']=1.038000,},[70]={['O']=19954,['N']='Hero of Elsweyr Home',['D']='Primary Residence. Perpetually Under Construction.',['C']=1.042000,},[16]={['O']=19810,['N']='Heart\\'s Day Retreat',['D']='Ember and Mirri\\'s \"secret\" retreat for when they want to be alone together. Mirri used her trading skills to procure decorations, and Ember used her magic to add a little romantic flair. ',['C']=1.022000,},[22]={['O']=19954,['N']='Khajiiti Home',['D']='Ezabi and Fezez\\'s home, where they relax with friends and family when they\\'re not working. A home where most things are adjusted to Alfiq height. Just a cozy home.',['C']=1.026000,},[7]={['O']=19749,['N']='Khajit Hideaway',['D']='there\\'s nothing here, just for quick teleports',['C']=1.006000,},[96]={['O']=19954,['N']='Maormer Manor',['D']='Pre-furnished with minimal changes.',['C']=1.500000,},[28]={['O']=20286,['N']='Tea Party',['D']='there\\'s nothing here, just for quick teleports',['C']=1.006000,},[27]={['O']=19366,['N']='Companions\\' Hall',['D']='The companions needed their own home, a place to relax, play games, and just be themselves. To make their life easier, Brahgas does the cooking and cleaning. Each companion has put a little bit of a personal touch on their bedrooms. And yes, there is a reason that Ember and Mirri share a room.',['C']=1.042000,},[59]={['O']=19954,['N']='Alinor Manor of Cake',['D']='Pre-furnished with minimal changes.',['C']=1.051000,},[44]={['O']=19749,['N']='Redoran Home',['D']='there\\'s nothing here, it\\'s just for quick teleports',['C']=1.006000,},[13]={['O']=19749,['N']='Little Crafting Pod',['D']='quick teleport and also basic crafting',['C']=1.006000,},[30]={['O']=19749,['N']='Mistveil Manor',['D']='nothing here just quick teleport',['C']=1.006000,},[63]={['O']=19749,['N']='The Cold Place',['D']='nothing here just quick teleport',['C']=1.006000,},},['Key']='oh__@wingedcatninja',['TS']=1752773308,}"
