R["oh__@laughyena"]="{['TS']=1686855879,['Version']=1773,['na']={[100]={['D']='A Redguard funeral tomb.',['O']=19520,['C']=1.007000,['N']='Necrom Inn',},[27]={['D']='Visit this relaxing Botanical Gardens and Aquarium research!',['O']=19506,['C']=1.012000,['N']='Aquarium and Gardens',},[91]={['C']=1.007000,['O']=19523,['D']='Ayem\\'s Embrace Orphanage is located in Deshan and serves primarily to Dunmer though it accepts all unfortunate children in the region. Head mistress  Gyae Lloran strives to create a safe space of learing and healing for children during their difficult loss and time of transition.',['N']='Mother\\'s Embrace Orp',},[71]={['C']=1.021000,['O']=19523,['D']='Come to relax, to enjoy a small hedge maze, a market place, a place to worship the Tribunal or just enjoy the gardens. ',['N']='Deshaan Meadows',},},['Key']='oh__@laughyena',}"
