R["fx__eu__@flammenderose__62"]="{['Version']=1771,['Effects']={[1]={['Roll']=0,['EffectType']=8502,['SizeX']=26.456456,['Yaw']=1.183333,['X']=81148.078749,['Pitch']=4.729842,['Alpha']=1,['Z']=62265.298233,['Groups']=0,['MetaData']={['title']='Lost Diary',['message']='Find the Statues...\\n\\nFour Statues open the path...\\n\\n\\nThe Tower of Control is my only hope... \\n\\n\\nAlways follow the cats\\n\\n\\nAnd by all means. Dont fall for the illusion outside of the black walls. It looks nice and welcoming... but i saw someone getting torn apart...by the air itself. Dont go there.',},['SizeZ']=30,['Id']=1011,['Color']=102439,['Contrast']=1,['Y']=10660,['SizeY']=30,},[2]={['Roll']=0,['EffectType']=8501,['SizeX']=26.456456,['Yaw']=4.232423,['X']=86850.236647,['Pitch']=4.757768,['Alpha']=1,['Z']=58905.567925,['Groups']=0,['MetaData']={['title']='Torn Page',['message']='\\n\\n\\n\\n\\n\\n\\n\\n\\nI almost lost my whole foot. \\nBut what are they hiding?',},['SizeZ']=30,['Id']=1012,['Color']=909899,['Contrast']=1.110000,['Y']=9818,['SizeY']=30,},[3]={['Roll']=0,['EffectType']=8501,['SizeX']=26.456456,['Yaw']=2.474877,['X']=80216.892647,['Pitch']=1.623156,['Alpha']=1,['Z']=65537.767199,['Groups']=0,['MetaData']={['title']='Bloody Page',['message']='\\n\\n\\n\\n\\nIm getting dizzy just looking up...\\nThere better be something importent up there.',},['SizeZ']=30,['Id']=1013,['Color']=20523,['Contrast']=1,['Y']=10758,['SizeY']=30,},[4]={['Roll']=0,['EffectType']=8501,['SizeX']=26.456456,['Yaw']=5.139995,['X']=73961.526094,['Pitch']=5.131268,['Alpha']=1,['Z']=65310.177641,['Groups']=0,['MetaData']={['title']='Confused Page',['message']='\\n\\n\\n\\nThere was another path at the end. \\nBut where did it come from? ',},['SizeZ']=30,['Id']=1015,['Color']=799399,['Contrast']=2.120000,['Y']=12636,['SizeY']=30,},[5]={['Roll']=0,['EffectType']=8501,['SizeX']=26.456456,['Yaw']=5.318018,['X']=75804.868666,['Pitch']=4.796165,['Alpha']=1,['Z']=64503.961406,['Groups']=0,['MetaData']={['title']='Desperate Note',['message']='\\n\\n\\nI made it!\\nIts obvious, now i just need to build the path from here!\\n\\nBut...wait.\\nHow do i even get to the left tower...',},['SizeZ']=30,['Id']=1016,['Color']=455460,['Contrast']=2,['Y']=14330,['SizeY']=30,},[6]={['Roll']=0,['EffectType']=8501,['SizeX']=22,['Yaw']=5.028294,['X']=77496.256209,['Pitch']=1.745329,['Alpha']=1,['Z']=63633.656918,['Groups']=0,['MetaData']={['title']='almost unreadable note',['message']='\\n\\n\\n\\n\\nHow was the tower-door still closed???',},['SizeZ']=30,['Id']=1017,['Color']=151819,['Contrast']=1.540000,['Y']=11419,['SizeY']=30,},},['TS']=1671656110,}"
