R["fx__na__@trasse__4"]="{['Version']=1767,['Effects']={[1]={['Alpha']=0,['EffectType']=5010,['Yaw']=1.473058,['Contrast']=1,['Z']=24225.485075,['Y']=10139,['SizeZ']=235,['Groups']=0,['Id']=1574,['Roll']=0,['SizeX']=90,['SizeY']=235,['Color']=696969,['Pitch']=0,['X']=23518.703929,['MetaData']={['name']='Uncle Sweetshare',['message']='Candy, candy! He makes so much! Uncle Sweetshare has a magic touch! When the sugar is warmed by the pale hearth light, the happiness spreads throughout the night!',},},[2]={['Alpha']=1,['EffectType']=8502,['Yaw']=3.550000,['Contrast']=1,['Z']=24623.275867,['Y']=10127,['SizeZ']=30,['Groups']=0,['Id']=1579,['Roll']=0,['SizeX']=26.456456,['SizeY']=30,['Color']=132192,['Pitch']=4.712564,['X']=23482.754119,['MetaData']={['title']='The Song of Uncle Sweetshare',['message']='He he! Ha ho!\\n\\nTo the workshop he will go!\\n\\nMy Uncle\\'s candy is so sweet!\\n\\nIt\\'s such a yummy winter\\'s treat!\\n\\nWhen the sugar is warmed by the pale hearth light\\n\\nThe happiness spreads throughout the night!\\n\\nHe he! Ha ho!\\n\\nTo the workshop he will go!\\n\\nUncle Sweetshare is coming near\\n\\nTo spread his candy and his cheer!\\n\\nIt\\'s better than trinkets, games or toys\\n\\nSo say all the little girls and boys!\\n\\nHe he! Ha ho!\\n\\nTo the workshop he will go!\\n\\nCandy, candy -- he makes so much!\\n\\nUncle Sweetshare has a magic touch!\\n\\nSo it\\'s back to the workshop in the snow!\\n\\nWith lovely lanterns all aglow!\\n\\nHe he! Ha ho! He he he ha ha ho!',},},[3]={['Alpha']=0,['EffectType']=5010,['Yaw']=1.478290,['Contrast']=1,['Z']=24225.612761,['Y']=10139,['SizeZ']=235,['Groups']=0,['Id']=1576,['Roll']=0,['SizeX']=90,['SizeY']=235,['Color']=696968,['Pitch']=0,['X']=23519.522358,['MetaData']={['name']='Uncle Sweetshare',['message']='So it\\'s back to the workshop in the snow! With lovely lanterns all aglow! Heehee! Ha ho! Heehee ha ha ho!',},},},['TS']=1639968991,}"
